        "direction": "up",
        "magnitude": "strong",
        "rationale": "Credible intelligence suggesting increased use and normalization by Russia increases the probability of any state actor employing chemical weapons."
      },
      {
        "factor": "Escalating conflict dynamics and repeated incidents increase opportunity for chemical-weapons use",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "More intense fighting creates incentives and opportunities for signaling chemical-use during offensives or stalemates."
